#!/usr/bin/env python3
"""Actual pinned Fumen chart string fields, including normalized SM headers."""
import argparse,hashlib,json,subprocess,tempfile
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--reference-root',type=Path,required=True);p.add_argument('--dotnet',required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();root=a.reference_root/'Fumen';pin='0fe292f9c0ef70fb77d61cb54316a7e78dbf3c89';assert subprocess.check_output(['git','-C',str(root),'rev-parse','HEAD'],text=True).strip()==pin;dll=root/'Fumen/bin/Release/net10.0/Fumen.dll'
program=r'''using System;using System.IO;using Path=System.IO.Path;using System.Collections.Generic;using System.Text.Json;using System.Threading;using Fumen;using Fumen.ChartDefinition;using Fumen.Converters;
class Program {static async System.Threading.Tasks.Task Main(){var output=new List<object>();var directory=Path.Combine(Path.GetTempPath(),"literal-text-"+Guid.NewGuid());Directory.CreateDirectory(directory);try{foreach(var format in new[]{"sm","ssc"})foreach(var raw in new[]{" ","  edge.png  ","a\\/b\\;c"," // comment\n  edge.png  ","\tname\t"}){var path=Path.Combine(directory,"song."+format);var input="#TITLE:source;#CREDIT:global-credit;#MUSIC:global.ogg;#BPMS:0=120;"+(format=="sm"?"#NOTES: dance-single :"+raw+": Easy : 1 ::0000;":"#VERSION:0.83;#NOTEDATA:;#STEPSTYPE: dance-single ;#CHARTNAME:"+raw+";#CHARTSTYLE:"+raw+";#DESCRIPTION:"+raw+";#CREDIT:"+raw+";#MUSIC:"+raw+";#NOTES:0000;");File.WriteAllText(path,input);Song song=format=="sm"?await new SMReader(path).LoadAsync(CancellationToken.None):await new SSCReader(path).LoadAsync(CancellationToken.None);var chart=song.Charts[0];chart.Extras.TryGetExtra("CHARTNAME",out string name,true);chart.Extras.TryGetExtra("CHARTSTYLE",out string style,true);output.Add(new{format,raw,input,name,style,description=chart.Description,credit=chart.Author,music=chart.MusicFile,type=chart.Type});}}finally{Directory.Delete(directory,true);}Console.Write(JsonSerializer.Serialize(output));}}
'''
with tempfile.TemporaryDirectory(prefix='fumen-literal-text-')as temp:
 t=Path(temp);(t/'Program.cs').write_text(program);(t/'Oracle.csproj').write_text(f'<Project Sdk="Microsoft.NET.Sdk"><PropertyGroup><OutputType>Exe</OutputType><TargetFramework>net10.0</TargetFramework></PropertyGroup><ItemGroup><Reference Include="Fumen"><HintPath>{dll}</HintPath></Reference></ItemGroup></Project>');r=subprocess.run([a.dotnet,'run','--project',str(t/'Oracle.csproj'),'--verbosity','quiet'],capture_output=True,text=True,check=True);result=json.loads(next(line for line in r.stdout.splitlines()if line.startswith('[')))
a.output.parent.mkdir(parents=True,exist_ok=True);a.output.write_text(json.dumps(result,indent=2)+'\n');a.output.with_suffix('.reference.json').write_text(json.dumps({'FumenCommit':pin,'DllSha256':hashlib.sha256(dll.read_bytes()).hexdigest(),'HostSha256':hashlib.sha256(program.encode()).hexdigest(),'Scope':'Actual complete original SMReader/SSCReader/MSDFile/property parsers, with proper semicolon termination. No direct setter stub or trim emulation.'},indent=2)+'\n');print('Executed',len(result),'real reader whitespace cases.')
